@tool
class_name EquipmentDefinition
extends Resource

## One piece of equipment.
##
## Everything the player sees and does while this item is active is derived from
## this single resource: the displayed model and its camera mount, the crosshair
## visibility and style, and the attack mode, damage, range, cooldown and
## ammunition. No other node keeps a second copy of "what is equipped", so a
## model that edits damage or swaps the mesh cannot desynchronise the interface.

enum AttackMode { NONE, RANGED, MELEE }

@export var id: StringName = &""
@export var display_name: String = ""
@export_multiline var description: String = ""

@export_group("Attack")
@export var attack_mode: AttackMode = AttackMode.NONE
@export var damage: float = 10.0
@export var cooldown_seconds: float = 0.4
@export var range_meters: float = 60.0
## Ranged: number of rays per shot. Melee ignores this.
@export var pellets: int = 1
## Ranged: cone half-width in degrees. Zero means a perfectly straight shot.
@export var spread_degrees: float = 0.0
## Melee: full arc width in degrees around the aim direction.
@export var melee_arc_degrees: float = 70.0
@export_flags_3d_physics var hit_mask: int = 3

@export_group("Ammunition")
## Magazine capacity. Zero means the item never consumes ammunition.
@export var magazine_size: int = 0
@export var reload_seconds: float = 1.2
## Rounds in the magazine at a fresh start. Negative means "full magazine".
@export var starting_ammo: int = -1
## Rounds held in reserve at a fresh start. Reloading draws from here.
@export var starting_reserve: int = 0

@export_group("Display")
@export var display_mesh: Mesh
@export var display_material: Material
## Position of the model under the camera. The model is a child of the camera,
## so it always follows the real camera transform.
@export var mount_offset: Vector3 = Vector3(0.24, -0.20, -0.42)
@export var mount_rotation_degrees: Vector3 = Vector3.ZERO
@export var display_scale: Vector3 = Vector3.ONE

@export_group("Interface")
@export var crosshair_visible: bool = true
@export var crosshair_style: CrosshairStyle


func uses_ammo() -> bool:
	return magazine_size > 0


func initial_ammo() -> int:
	if not uses_ammo():
		return 0
	return magazine_size if starting_ammo < 0 else clampi(starting_ammo, 0, magazine_size)


func attack_mode_name() -> String:
	return ["NONE", "RANGED", "MELEE"][int(attack_mode)]


## Returns the first problem that would make this definition unusable, or "".
func validate() -> String:
	if id.is_empty():
		return "Equipment id is empty"
	if damage < 0.0 or not is_finite(damage):
		return String(id) + ": damage must be a finite non-negative number"
	if cooldown_seconds < 0.0 or not is_finite(cooldown_seconds):
		return String(id) + ": cooldown must be a finite non-negative number"
	if range_meters <= 0.0 or not is_finite(range_meters):
		return String(id) + ": range must be a finite positive number"
	if magazine_size < 0:
		return String(id) + ": magazine size cannot be negative"
	if reload_seconds < 0.0:
		return String(id) + ": reload time cannot be negative"
	if attack_mode == AttackMode.RANGED and pellets < 1:
		return String(id) + ": a ranged item needs at least one pellet"
	if crosshair_visible and crosshair_style == null:
		return String(id) + ": a visible crosshair needs a style resource"
	return ""

@tool
class_name EquipmentCatalog
extends Resource

## Ordered list of equipment a world can equip. The order is the switch order,
## so the list is data a model can reorder without touching any script.

@export var default_id: StringName = &""
@export var items: Array[EquipmentDefinition] = []


func ids() -> Array[StringName]:
	var result: Array[StringName] = []
	for definition in items:
		if definition != null:
			result.append(definition.id)
	return result


func has_id(id: StringName) -> bool:
	return definition_for(id) != null


func definition_for(id: StringName) -> EquipmentDefinition:
	for definition in items:
		if definition != null and definition.id == id:
			return definition
	return null


func index_of(id: StringName) -> int:
	for index in items.size():
		var definition := items[index]
		if definition != null and definition.id == id:
			return index
	return -1


func next_id(id: StringName) -> StringName:
	if items.is_empty():
		return &""
	var index := index_of(id)
	if index < 0:
		return items[0].id if items[0] != null else &""
	for step in range(1, items.size() + 1):
		var candidate := items[(index + step) % items.size()]
		if candidate != null:
			return candidate.id
	return id


func validate() -> String:
	if items.is_empty():
		return "Equipment catalog is empty"
	var seen := {}
	for definition in items:
		if definition == null:
			return "Equipment catalog contains a null entry"
		var problem := definition.validate()
		if not problem.is_empty():
			return problem
		if seen.has(definition.id):
			return "Duplicate equipment id: " + String(definition.id)
		seen[definition.id] = true
	if not default_id.is_empty() and not seen.has(default_id):
		return "Default equipment is not in the catalog: " + String(default_id)
	return ""

class_name EquipmentState
extends Node

## The single source of truth for the equipped item, its ammunition and its
## cooldown. The crosshair, the displayed model, the HUD and the attack
## dispatcher all observe this node instead of keeping their own copy.
##
## Cooldown and reload timers are per item. Switching weapons therefore cannot
## cancel a cooldown or a reload for free, and a timer that is still running when
## an item is re-equipped keeps its remaining time.

signal equipment_changed(id: StringName, definition: EquipmentDefinition)
signal ammo_changed(id: StringName, magazine: int, capacity: int, reserve: int)
signal cooldown_changed(id: StringName, remaining: float, total: float)
signal reload_changed(id: StringName, reloading: bool, progress: float)

@export var catalog: EquipmentCatalog

var active_id: StringName = &""
var _magazine: Dictionary = {}
var _reserve: Dictionary = {}
var _cooldown_remaining: Dictionary = {}
var _cooldown_total: Dictionary = {}
var _reload_remaining: Dictionary = {}
var _reload_total: Dictionary = {}


func _ready() -> void:
	if catalog == null:
		push_error("EquipmentState requires an EquipmentCatalog")
		set_physics_process(false)
		return
	var problem := catalog.validate()
	if not problem.is_empty():
		push_error("Equipment catalog is invalid: " + problem)
		set_physics_process(false)
		return
	for definition in catalog.items:
		_magazine[definition.id] = definition.initial_ammo()
		_reserve[definition.id] = maxi(0, definition.starting_reserve)
		_cooldown_remaining[definition.id] = 0.0
		_cooldown_total[definition.id] = 0.0
		_reload_remaining[definition.id] = 0.0
		_reload_total[definition.id] = 0.0
	var initial := catalog.default_id
	if initial.is_empty():
		initial = catalog.items[0].id
	set_physics_process(true)
	equip(initial)


func _physics_process(delta: float) -> void:
	var ticked := false
	for id in _cooldown_remaining.keys():
		if float(_cooldown_remaining[id]) > 0.0:
			_cooldown_remaining[id] = maxf(0.0, float(_cooldown_remaining[id]) - delta)
			ticked = true
	for id in _reload_remaining.keys():
		if float(_reload_remaining[id]) > 0.0:
			_reload_remaining[id] = maxf(0.0, float(_reload_remaining[id]) - delta)
			if float(_reload_remaining[id]) <= 0.0:
				_finish_reload(id)
			ticked = true
	if ticked:
		cooldown_changed.emit(active_id, cooldown_remaining(), cooldown_total())
		reload_changed.emit(active_id, is_reloading(), reload_progress())


# --------------------------------------------------------------------------
# Queries
# --------------------------------------------------------------------------

func definition() -> EquipmentDefinition:
	if catalog == null:
		return null
	return catalog.definition_for(active_id)


func definition_for(id: StringName) -> EquipmentDefinition:
	if catalog == null:
		return null
	return catalog.definition_for(id)


func magazine() -> int:
	return int(_magazine.get(active_id, 0))


func reserve() -> int:
	return int(_reserve.get(active_id, 0))


func capacity() -> int:
	var definition := definition()
	return definition.magazine_size if definition != null else 0


func cooldown_remaining() -> float:
	return float(_cooldown_remaining.get(active_id, 0.0))


func cooldown_total() -> float:
	return float(_cooldown_total.get(active_id, 0.0))


func cooldown_ratio() -> float:
	var total := cooldown_total()
	if total <= 0.0:
		return 0.0
	return clampf(cooldown_remaining() / total, 0.0, 1.0)


func is_reloading() -> bool:
	return float(_reload_remaining.get(active_id, 0.0)) > 0.0


func reload_progress() -> float:
	var total := float(_reload_total.get(active_id, 0.0))
	if total <= 0.0:
		return 1.0
	return clampf(1.0 - float(_reload_remaining.get(active_id, 0.0)) / total, 0.0, 1.0)


## Why an attack cannot start right now: "", "no-equipment", "no-attack",
## "cooling-down", "reloading" or "empty".
func attack_block_reason() -> String:
	var definition := definition()
	if definition == null:
		return "no-equipment"
	if definition.attack_mode == EquipmentDefinition.AttackMode.NONE:
		return "no-attack"
	if cooldown_remaining() > 0.0:
		return "cooling-down"
	if is_reloading():
		return "reloading"
	if definition.uses_ammo() and magazine() <= 0:
		return "empty"
	return ""


# --------------------------------------------------------------------------
# Commands
# --------------------------------------------------------------------------

## Selects an item. It deliberately does not touch that item's cooldown or
## reload timers, so switching away and back cannot skip a cost.
func equip(id: StringName) -> bool:
	var definition := definition_for(id)
	if definition == null:
		push_warning("Unknown equipment: " + String(id))
		return false
	active_id = id
	equipment_changed.emit(active_id, definition)
	ammo_changed.emit(active_id, magazine(), capacity(), reserve())
	cooldown_changed.emit(active_id, cooldown_remaining(), cooldown_total())
	reload_changed.emit(active_id, is_reloading(), reload_progress())
	return true


func equip_next() -> bool:
	if catalog == null:
		return false
	return equip(catalog.next_id(active_id))


## Consumes ammunition and starts the cooldown, then hands back the definition
## the dispatcher must execute. Returns {"ok": false, "reason": ...} otherwise.
func try_begin_attack() -> Dictionary:
	var reason := attack_block_reason()
	if not reason.is_empty():
		return {"ok": false, "reason": reason, "definition": definition()}
	var definition := definition()
	if definition.uses_ammo():
		_magazine[active_id] = magazine() - 1
		ammo_changed.emit(active_id, magazine(), capacity(), reserve())
	_cooldown_total[active_id] = definition.cooldown_seconds
	_cooldown_remaining[active_id] = definition.cooldown_seconds
	cooldown_changed.emit(active_id, cooldown_remaining(), cooldown_total())
	return {"ok": true, "reason": "", "definition": definition}


func request_reload() -> bool:
	var definition := definition()
	if definition == null or not definition.uses_ammo():
		return false
	if is_reloading() or magazine() >= capacity() or reserve() <= 0:
		return false
	_reload_total[active_id] = definition.reload_seconds
	_reload_remaining[active_id] = definition.reload_seconds
	if float(_reload_remaining[active_id]) <= 0.0:
		_finish_reload(active_id)
	else:
		reload_changed.emit(active_id, true, 0.0)
	return true


## Adds rounds to the reserve of the active item. If the active item cannot hold
## ammunition, the rounds go to the first catalog item that can, so a reward is
## never silently lost while a melee item is equipped. Returns the rounds stored.
func add_reserve(rounds: int) -> int:
	if rounds <= 0:
		return 0
	var target := active_id if _uses_ammo(active_id) else _first_ammo_item()
	if target.is_empty():
		return 0
	return add_reserve_for(target, rounds)


func add_reserve_for(id: StringName, rounds: int) -> int:
	if rounds <= 0 or definition_for(id) == null:
		return 0
	_reserve[id] = int(_reserve.get(id, 0)) + rounds
	if id == active_id:
		ammo_changed.emit(active_id, magazine(), capacity(), reserve())
	return rounds


func _uses_ammo(id: StringName) -> bool:
	var definition := definition_for(id)
	return definition != null and definition.uses_ammo()


func _first_ammo_item() -> StringName:
	if catalog == null:
		return &""
	for definition in catalog.items:
		if definition != null and definition.uses_ammo():
			return definition.id
	return &""


func _finish_reload(id: StringName) -> void:
	var definition := definition_for(id)
	_reload_remaining[id] = 0.0
	_reload_total[id] = 0.0
	if definition == null:
		return
	var current := int(_magazine.get(id, 0))
	var available := int(_reserve.get(id, 0))
	var moved := mini(definition.magazine_size - current, available)
	if moved > 0:
		_magazine[id] = current + moved
		_reserve[id] = available - moved
	if id == active_id:
		ammo_changed.emit(active_id, magazine(), capacity(), reserve())
		reload_changed.emit(active_id, false, 1.0)


# --------------------------------------------------------------------------
# Persistence
# --------------------------------------------------------------------------

func snapshot() -> Dictionary:
	var items := []
	if catalog != null:
		for definition in catalog.items:
			if definition == null:
				continue
			items.append({
				"id": String(definition.id),
				"magazine": int(_magazine.get(definition.id, 0)),
				"reserve": int(_reserve.get(definition.id, 0)),
			})
	return {"active": String(active_id), "items": items}


## Applies a saved equipment block. Returns "" on success, otherwise a message
## that explains why nothing was changed.
##
## Authored maxima (magazine size) are source and may shrink between builds, so a
## saved magazine above the current maximum is clamped rather than rejected. A
## source edit must not discard the player's progress.
func restore(data: Dictionary) -> String:
	if not data.get("active") is String:
		return "Equipment state has no active item"
	if not data.get("items") is Array:
		return "Equipment state has no item list"
	var restored_magazine := {}
	var restored_reserve := {}
	for entry in data.items:
		if not entry is Dictionary:
			return "Equipment entry is not an object"
		var id := StringName(str(entry.get("id", "")))
		var definition := definition_for(id)
		if definition == null:
			return "Unknown equipment id in state: " + String(id)
		var magazine_value = entry.get("magazine")
		var reserve_value = entry.get("reserve")
		if not _is_int(magazine_value, 0, 99999):
			return "Invalid magazine for " + String(id)
		if not _is_int(reserve_value, 0, 99999):
			return "Invalid reserve for " + String(id)
		restored_magazine[id] = mini(int(magazine_value), definition.magazine_size)
		restored_reserve[id] = int(reserve_value)
	for definition in catalog.items:
		if definition != null and not restored_magazine.has(definition.id):
			return "State is missing equipment: " + String(definition.id)
	var next_active := StringName(str(data.active))
	if definition_for(next_active) == null:
		return "Unknown active equipment: " + str(data.active)
	_magazine = restored_magazine
	_reserve = restored_reserve
	equip(next_active)
	return ""


static func _is_int(value, minimum: int, maximum: int) -> bool:
	if not (value is float or value is int):
		return false
	var number := float(value)
	return is_finite(number) and number == floorf(number) and number >= float(minimum) and number <= float(maximum)

extends Node3D

const Contract = preload("res://scripts/scene_contract.gd")
const BASE_VERSION := "1.0.0"
const HALF_EXTENTS := {"tree": Vector3(0.6, 2, 0.6), "rock": Vector3(0.7, 0.7, 0.7), "chest": Vector3(0.6, 0.55, 0.5), "door": Vector3(0.8, 1.3, 0.25), "marker": Vector3(0.3, 0.7, 0.3)}
const INTERACTION_DISTANCE := 3.5
signal interacted(entity_id: String)

@onready var player: PlayerController = $Player
var scene_data: Dictionary = {}
var world_id := "creation-local"
var ready_for_play := false
var failure := ""
var entities := {}
var entity_nodes := {}
var rule_nodes := {}
var rule_state := {}
var inventory := {}
var opened_chests := {}
var doors := {}
var time_of_day := 12.0
var target := {"entityId": null, "position": null, "normal": null, "surface": "none", "revision": 1}
var marker: MeshInstance3D
var sun: DirectionalLight3D
var status_label: Label

func _ready() -> void:
	player.capture_mouse_on_click = DisplayServer.get_name() != "headless"
	player.input_enabled = DisplayServer.get_name() != "headless"
	_build_environment()
	_build_hud()
	var file := FileAccess.open("res://world/creation.json", FileAccess.READ)
	if file == null or file.get_length() > 131072:
		_fail("Creation source is missing or exceeds 128 KiB")
		return
	var raw: Variant = JSON.parse_string(file.get_as_text())
	file.close()
	failure = Contract.validate(raw)
	if not failure.is_empty():
		_fail(failure)
		return
	scene_data = raw
	time_of_day = float(scene_data.defaults.timeOfDay)
	for definition in scene_data.entities:
		entities[definition.id] = definition.duplicate(true)
		_create_entity(definition)
	for definition in scene_data.get("rules", []):
		var script_path: String = "res://" + definition.script
		if not FileAccess.file_exists(script_path) or FileAccess.get_sha256(script_path) != definition.sha256:
			_fail("Authored rule source hash mismatch: " + definition.id)
			return
		var resource: Variant = load(script_path)
		if not resource is Script or not resource.can_instantiate():
			_fail("Authored rule cannot be loaded: " + definition.id)
			return
		var rule: Variant = resource.new()
		if not rule is Node:
			_fail("Authored rule must extend Node: " + definition.id)
			return
		for method in ["configure", "on_entity_interacted", "snapshot", "validate_state", "restore"]:
			if not rule.has_method(method):
				_fail("Authored rule is missing " + method + ": " + definition.id)
				rule.free()
				return
		rule.name = "Rule_" + definition.id
		add_child(rule)
		rule.configure(self, definition.duplicate(true))
		rule_nodes[definition.id] = rule
	_update_time()
	ready_for_play = true
	status_label.text = "WASD 移动 · E 互动 · F2 创作"

func _fail(message: String) -> void:
	failure = message
	ready_for_play = false
	player.input_enabled = false
	status_label.text = "Creation world unavailable: " + message
	push_error(message)

func _material(color: Color, unshaded := false) -> StandardMaterial3D:
	var material := StandardMaterial3D.new()
	material.albedo_color = color
	material.roughness = 0.85
	if unshaded:
		material.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	return material

func _box(parent: Node3D, size: Vector3, center: Vector3, color: Color) -> MeshInstance3D:
	var mesh := MeshInstance3D.new()
	var box := BoxMesh.new()
	box.size = size
	mesh.mesh = box
	mesh.material_override = _material(color)
	mesh.position = center
	parent.add_child(mesh)
	return mesh

func _solid(parent: Node3D, size: Vector3, center: Vector3, surface: String, entity_id := "") -> StaticBody3D:
	var body := StaticBody3D.new()
	body.collision_layer = 2 if not entity_id.is_empty() else 1
	body.collision_mask = 8
	body.set_meta("surface", surface)
	body.set_meta("entity_id", entity_id)
	body.position = center
	var shape := CollisionShape3D.new()
	var box := BoxShape3D.new()
	box.size = size
	shape.shape = box
	body.add_child(shape)
	parent.add_child(body)
	return body

func _build_environment() -> void:
	var environment := WorldEnvironment.new()
	var settings := Environment.new()
	settings.background_mode = Environment.BG_SKY
	var sky := Sky.new()
	var sky_material := ProceduralSkyMaterial.new()
	sky_material.sky_top_color = Color("5282ad")
	sky_material.sky_horizon_color = Color("c6dfdf")
	sky.sky_material = sky_material
	settings.sky = sky
	settings.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	settings.ambient_light_color = Color("c8dfed")
	settings.ambient_light_energy = 0.7
	environment.environment = settings
	add_child(environment)
	sun = DirectionalLight3D.new()
	sun.shadow_enabled = true
	add_child(sun)
	_box(self, Vector3(64, 0.4, 64), Vector3(0, -0.2, 0), Color("6e9580"))
	_solid(self, Vector3(64, 0.4, 64), Vector3(0, -0.2, 0), "ground")
	for edge in [-1, 1]:
		var center := Vector3(edge * 32, 1.5, 0)
		_box(self, Vector3(0.5, 3, 64), center, Color("b2c5bf"))
		_solid(self, Vector3(0.5, 6, 64), Vector3(edge * 32, 3, 0), "boundary")
		center = Vector3(0, 1.5, edge * 32)
		_box(self, Vector3(64, 3, 0.5), center, Color("b2c5bf"))
		_solid(self, Vector3(64, 6, 0.5), Vector3(0, 3, edge * 32), "boundary")
	marker = MeshInstance3D.new()
	var sphere := SphereMesh.new()
	sphere.radius = 0.045
	sphere.height = 0.09
	marker.mesh = sphere
	marker.material_override = _material(Color("f8df87"), true)
	marker.visible = false
	add_child(marker)

func _build_hud() -> void:
	var layer := CanvasLayer.new()
	add_child(layer)
	var crosshair := Label.new()
	crosshair.text = "+"
	crosshair.mouse_filter = Control.MOUSE_FILTER_IGNORE
	crosshair.set_anchors_preset(Control.PRESET_CENTER)
	crosshair.position = Vector2(-5, -12)
	crosshair.add_theme_font_size_override("font_size", 22)
	layer.add_child(crosshair)
	status_label = Label.new()
	status_label.position = Vector2(20, 18)
	status_label.mouse_filter = Control.MOUSE_FILTER_IGNORE
	layer.add_child(status_label)

func _create_entity(definition: Dictionary) -> void:
	var node := Node3D.new()
	node.name = "Entity_" + definition.id
	add_child(node)
	node.position = Vector3(definition.position[0], definition.position[1], definition.position[2])
	node.rotation.y = deg_to_rad(float(definition.rotationY))
	node.scale = Vector3(definition.scale[0], definition.scale[1], definition.scale[2])
	entity_nodes[definition.id] = node
	var color := Color(definition.color)
	var half: Vector3 = HALF_EXTENTS[definition.kind]
	var body := _solid(node, half * 2, Vector3(0, half.y, 0), "entity", definition.id)
	body.name = "Body"
	match definition.kind:
		"tree":
			_box(node, Vector3(0.25, 2.2, 0.25), Vector3(0, 1.1, 0), Color("715c46"))
			var canopy := MeshInstance3D.new()
			var sphere := SphereMesh.new()
			sphere.radius = 0.6
			sphere.height = 2
			canopy.mesh = sphere
			canopy.position.y = 3
			canopy.material_override = _material(color)
			node.add_child(canopy)
		"rock":
			var rock := MeshInstance3D.new()
			var sphere := SphereMesh.new()
			sphere.radius = 0.7
			sphere.height = 1.4
			rock.mesh = sphere
			rock.position.y = 0.7
			rock.material_override = _material(color)
			node.add_child(rock)
		"chest":
			_box(node, Vector3(1.2, 0.8, 1), Vector3(0, 0.4, 0), color)
			var lid := Node3D.new()
			lid.name = "Lid"
			lid.position = Vector3(0, 0.85, -0.5)
			node.add_child(lid)
			_box(lid, Vector3(1.2, 0.25, 1), Vector3(0, 0.125, 0.5), color.lightened(0.15))
			_box(node, Vector3(0.2, 0.3, 0.05), Vector3(0, 0.65, 0.53), Color("e9c66e"))
		"door":
			var hinge := Node3D.new()
			hinge.name = "Hinge"
			hinge.position.x = -0.8
			node.add_child(hinge)
			# Open doors remain aimable even though their blocking collider is off.
			var aim_area := Area3D.new()
			aim_area.collision_layer = 4
			aim_area.collision_mask = 0
			aim_area.set_meta("surface", "entity")
			aim_area.set_meta("entity_id", definition.id)
			var aim_shape := CollisionShape3D.new()
			var aim_box := BoxShape3D.new()
			aim_box.size = Vector3(1.6, 2.6, 0.5)
			aim_shape.shape = aim_box
			aim_shape.position = Vector3(0.8, 1.3, 0)
			aim_area.add_child(aim_shape)
			hinge.add_child(aim_area)
			_box(hinge, Vector3(1.6, 2.6, 0.5), Vector3(0.8, 1.3, 0), color)
			_box(hinge, Vector3(0.12, 0.12, 0.12), Vector3(1.4, 1.3, 0.3), Color("f5d478"))
			doors[definition.id] = definition.parameters.get("initiallyOpen", false)
			_update_door(definition.id)
		"marker":
			_box(node, Vector3(0.16, 1.4, 0.16), Vector3(0, 0.7, 0), color)
			_box(node, Vector3(0.6, 0.35, 0.6), Vector3(0, 1.2, 0), color.lightened(0.2))
			var label := Label3D.new()
			label.text = definition.parameters.get("label", "")
			label.position.y = 1.7
			label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
			label.font_size = 36
			node.add_child(label)

func _physics_process(_delta: float) -> void:
	if ready_for_play:
		refresh_target()

func _unhandled_input(event: InputEvent) -> void:
	if ready_for_play and event.is_action_pressed("interact"):
		interact_target()

func refresh_target() -> Dictionary:
	target = {"entityId": null, "position": null, "normal": null, "surface": "none", "revision": int(scene_data.get("revision", 1))}
	if not ready_for_play:
		return target.duplicate(true)
	var camera: Camera3D = player.camera_rig.camera
	var origin := camera.global_position
	var query := PhysicsRayQueryParameters3D.create(origin, origin - camera.global_basis.z * 80, 7, [player.get_rid()])
	query.collide_with_areas = true
	var hit := get_world_3d().direct_space_state.intersect_ray(query)
	marker.visible = not hit.is_empty()
	if not hit.is_empty():
		var collider: Object = hit.collider
		var point: Vector3 = hit.position
		var normal: Vector3 = hit.normal
		var entity_id: String = collider.get_meta("entity_id", "")
		target = {"entityId": entity_id if not entity_id.is_empty() else null, "position": [point.x, point.y, point.z], "normal": [normal.x, normal.y, normal.z], "surface": collider.get_meta("surface", "none"), "revision": int(scene_data.revision)}
		marker.global_position = point + normal * 0.03
	return target.duplicate(true)

func interact_target() -> Dictionary:
	var aimed := refresh_target()
	if aimed.entityId == null or aimed.position == null:
		return {"interacted": false, "reason": "no-entity"}
	var point := Vector3(aimed.position[0], aimed.position[1], aimed.position[2])
	if player.camera_rig.camera.global_position.distance_to(point) > INTERACTION_DISTANCE:
		return {"interacted": false, "reason": "out-of-range"}
	var id: String = aimed.entityId
	var definition: Dictionary = entities[id]
	match definition.kind:
		"chest":
			if opened_chests.has(id):
				return {"interacted": false, "reason": "already-opened", "entityId": id}
			var reward: String = definition.parameters.get("rewardId", "creation-token")
			var count: int = int(definition.parameters.get("rewardCount", 1))
			if int(inventory.get(reward, 0)) + count > 999999 or (not inventory.has(reward) and inventory.size() >= 4096):
				return {"interacted": false, "reason": "inventory-limit"}
			inventory[reward] = int(inventory.get(reward, 0)) + count
			opened_chests[id] = true
			_update_chest(id)
		"door":
			for rule in scene_data.get("rules", []):
				if rule.doorId == id:
					return {"interacted": false, "reason": "rule-controlled", "entityId": id}
			set_door_open(id, not doors.get(id, false))
		"marker":
			pass
		_:
			return {"interacted": false, "reason": "not-interactive"}
	interacted.emit(id)
	for rule in rule_nodes.values():
		rule.on_entity_interacted(id)
	return {"interacted": true, "entityId": id, "kind": definition.kind}

func set_door_open(id: String, opened: bool) -> bool:
	if not entities.has(id) or entities[id].kind != "door":
		return false
	doors[id] = opened
	_update_door(id)
	return true

func _update_door(id: String) -> void:
	var node: Node3D = entity_nodes[id]
	node.get_node("Hinge").rotation.y = -PI * 0.5 if doors.get(id, false) else 0.0
	var shape: CollisionShape3D = node.get_node("Body").get_child(0)
	shape.set_deferred("disabled", doors.get(id, false))

func _update_chest(id: String) -> void:
	if entity_nodes.has(id) and entities[id].kind == "chest":
		entity_nodes[id].get_node("Lid").rotation.x = -1.15 if opened_chests.has(id) else 0.0

func _update_time() -> void:
	sun.rotation_degrees = Vector3(-70 * sin(time_of_day / 24.0 * PI) - 5, -35, 0)
	sun.light_energy = 0.2 + 0.9 * maxf(0, sin(time_of_day / 24.0 * PI))

func set_time(hours: float) -> String:
	if not Contract.finite(hours, 0, 24):
		return "Time must be 0..24"
	time_of_day = hours
	_update_time()
	return ""

func capture() -> Dictionary:
	var rules := rule_state.duplicate(true)
	for id in rule_nodes:
		rules[id] = rule_nodes[id].snapshot()
	return {"format": "craftmine.creation-progress/1", "worldId": world_id, "baseVersion": BASE_VERSION, "player": player.snapshot(), "timeOfDay": time_of_day, "sourceTimeOfDay": float(scene_data.defaults.timeOfDay), "inventory": inventory.duplicate(true), "openedChests": opened_chests.duplicate(true), "doors": doors.duplicate(true), "rules": rules}

func validate_progress(data: Variant) -> String:
	if not Contract.fields(data, ["format", "worldId", "baseVersion", "player", "timeOfDay", "sourceTimeOfDay", "inventory", "openedChests", "doors", "rules"]) or data.format != "craftmine.creation-progress/1" or data.worldId != world_id or data.baseVersion != BASE_VERSION:
		return "Creation progress identity or fields do not match"
	if JSON.stringify(data).to_utf8_buffer().size() > 262144 or not _json_value(data, 0):
		return "Creation progress exceeds safe JSON limits"
	if not Contract.finite(data.sourceTimeOfDay, 0, 24) or data.sourceTimeOfDay != scene_data.defaults.timeOfDay:
		return "Creation progress needs the current source time default"
	if not Contract.finite(data.timeOfDay, 0, 24):
		return "Invalid saved time"
	if not Contract.fields(data.player, ["position", "yaw", "pitch", "onFloor"]) or not data.player.onFloor is bool:
		return "Invalid saved player"
	var p: Variant = data.player.position
	if not p is Array or p.size() != 3 or not Contract.finite(p[0], -32, 32) or not Contract.finite(p[1], 0, 32) or not Contract.finite(p[2], -32, 32) or not Contract.finite(data.player.yaw, -PI, PI) or not Contract.finite(data.player.pitch, -deg_to_rad(89), deg_to_rad(89)):
		return "Saved player pose is outside the sandbox"
	for key in ["inventory", "openedChests", "doors", "rules"]:
		if not data[key] is Dictionary or data[key].size() > 4096:
			return "Invalid saved ledger: " + key
		for id in data[key]:
			if not Contract.identifier(id):
				return "Invalid saved stable ID"
	for id in data.inventory:
		if not Contract.integer(data.inventory[id], 0, 999999):
			return "Invalid inventory count"
	for id in data.openedChests:
		if not data.openedChests[id] is bool or data.openedChests[id] != true:
			return "Invalid one-time chest ledger"
	for id in data.doors:
		if not data.doors[id] is bool:
			return "Invalid saved door state"
	for id in data.rules:
		if not data.rules[id] is Dictionary:
			return "Invalid saved rule state"
		if rule_nodes.has(id):
			var problem: Variant = rule_nodes[id].validate_state(data.rules[id])
			if not problem is String or not problem.is_empty():
				return "Authored rule rejected progress: " + id + ": " + str(problem)
	# Candidate defaults must be merged by the host and verified before adoption.
	# A direct restore never silently adds identities to the supplied snapshot.
	for id in entities:
		if entities[id].kind == "door" and not data.doors.has(id):
			return "Creation progress needs the new door default: " + id
	for definition in scene_data.get("rules", []):
		if not data.rules.has(definition.id):
			return "Creation progress needs the new rule default: " + definition.id
		if data.rules[definition.id].get("completed", false) and not data.doors.get(definition.doorId, false):
			return "Completed rule requires its open door: " + definition.id
	var collision := _player_overlap(Vector3(p[0], p[1], p[2]), data.doors)
	if not collision.is_empty():
		return "Saved player overlaps candidate entity: " + collision
	return ""

func _player_overlap(player_position: Vector3, saved_doors: Dictionary) -> String:
	# Capsule versus each actual Y-rotated box, before mutating any progress.
	# Use the proposed door state, not fresh-instance/default collider state.
	# A tiny contact tolerance preserves valid saves taken against a wall.
	for id in entities:
		var definition: Dictionary = entities[id]
		if definition.kind == "door" and saved_doors.get(id, false):
			continue
		var offset := player_position - Vector3(definition.position[0], definition.position[1], definition.position[2])
		var local := offset.rotated(Vector3.UP, -deg_to_rad(float(definition.rotationY)))
		var half: Vector3 = HALF_EXTENTS[definition.kind] * Vector3(definition.scale[0], definition.scale[1], definition.scale[2])
		var dx := maxf(absf(local.x) - half.x, 0)
		var dz := maxf(absf(local.z) - half.z, 0)
		var dy := maxf(maxf(-local.y - 0.6, local.y - 0.6 - half.y * 2), 0)
		if dx * dx + dy * dy + dz * dz < 0.298 * 0.298:
			return id
	return ""

func _json_value(value: Variant, depth: int) -> bool:
	if depth > 12:
		return false
	if value is Dictionary:
		if value.size() > 4096:
			return false
		for key in value:
			if not key is String or key.length() > 128 or not _json_value(value[key], depth + 1):
				return false
	elif value is Array:
		if value.size() > 4096:
			return false
		for item in value:
			if not _json_value(item, depth + 1):
				return false
	elif value is float or value is int:
		return is_finite(float(value))
	elif value is String:
		return value.length() <= 4096
	elif value != null and not value is bool:
		return false
	return true

func restore(data: Dictionary) -> String:
	var problem := validate_progress(data)
	if not problem.is_empty():
		return problem
	problem = player.restore(data.player)
	if not problem.is_empty():
		return problem
	time_of_day = float(data.timeOfDay)
	inventory = data.inventory.duplicate(true)
	opened_chests = data.openedChests.duplicate(true)
	doors = data.doors.duplicate(true)
	rule_state = data.rules.duplicate(true)
	for id in entities:
		if entities[id].kind == "door":
			if not doors.has(id):
				doors[id] = entities[id].parameters.get("initiallyOpen", false)
			_update_door(id)
		elif entities[id].kind == "chest":
			_update_chest(id)
	for id in rule_nodes:
		if rule_state.has(id):
			rule_nodes[id].restore(rule_state[id])
	_update_time()
	return ""

func save_local() -> String:
	var body := capture()
	var problem := validate_progress(body)
	if not problem.is_empty():
		return problem
	var destination := "user://creation-" + world_id + ".json"
	var file := FileAccess.open(destination + ".tmp", FileAccess.WRITE)
	if file == null:
		return "Cannot write creation progress"
	file.store_string(JSON.stringify(body))
	file.close()
	return "" if DirAccess.rename_absolute(destination + ".tmp", destination) == OK else "Cannot confirm creation progress"

func load_local() -> String:
	var destination := "user://creation-" + world_id + ".json"
	if not FileAccess.file_exists(destination):
		return "Creation progress is absent"
	var file := FileAccess.open(destination, FileAccess.READ)
	if file == null or file.get_length() > 262144:
		return "Cannot read bounded creation progress"
	var data: Variant = JSON.parse_string(file.get_as_text())
	file.close()
	if not data is Dictionary:
		return "Creation progress is malformed"
	return restore(data)

func observe() -> Dictionary:
	var definitions := []
	var obstacles := []
	for id in entities:
		var definition: Dictionary = entities[id].duplicate(true)
		if definition.kind == "chest": definition["opened"] = opened_chests.has(id)
		if definition.kind == "door": definition["open"] = doors.get(id, false)
		definitions.append(definition)
		if definition.kind == "door" and doors.get(id, false): continue
		var half: Vector3 = HALF_EXTENTS[definition.kind]
		var bounds: AABB = entity_nodes[id].global_transform * AABB(Vector3(-half.x, 0, -half.z), half * 2)
		obstacles.append({"entityId": id, "min": [bounds.position.x, bounds.position.y, bounds.position.z], "max": [bounds.end.x, bounds.end.y, bounds.end.z]})
	return {"base": "creation-sandbox", "baseVersion": BASE_VERSION, "player": player.snapshot(), "creation": {"revision": int(scene_data.get("revision", 1)), "target": refresh_target(), "entities": definitions, "obstacles": obstacles, "playerBounds": {"position": [player.position.x, player.position.y - 0.9, player.position.z], "halfExtents": [0.3, 0.9, 0.3]}, "timeOfDay": time_of_day}, "inventory": inventory.duplicate(true), "ready": ready_for_play, "error": failure}

extends RefCounted

const FORMAT := "craftmine.creation-scene/1"
const ID_PATTERN := "^[a-z][a-z0-9_-]{0,63}$"

static func identifier(value: Variant) -> bool:
	if not value is String:
		return false
	var pattern := RegEx.new()
	pattern.compile(ID_PATTERN)
	var found := pattern.search(value)
	return found != null and found.get_string() == value

static func finite(value: Variant, minimum: float, maximum: float) -> bool:
	return (value is float or value is int) and is_finite(float(value)) and value >= minimum and value <= maximum

static func integer(value: Variant, minimum: int, maximum: int) -> bool:
	return finite(value, minimum, maximum) and float(value) == floorf(float(value))

static func fields(value: Variant, required: Array, optional: Array = []) -> bool:
	if not value is Dictionary:
		return false
	for key in required:
		if not value.has(key):
			return false
	for key in value:
		if not key in required and not key in optional:
			return false
	return true

static func validate(scene: Variant) -> String:
	if not fields(scene, ["format", "revision", "defaults", "entities"], ["rules"]) or scene.format != FORMAT:
		return "Unsupported creation scene format or fields"
	if not integer(scene.revision, 1, 2147483647):
		return "Invalid creation scene revision"
	if not fields(scene.defaults, ["timeOfDay"]) or not finite(scene.defaults.timeOfDay, 0, 24):
		return "Invalid default timeOfDay"
	if not scene.entities is Array or scene.entities.size() > 128:
		return "Creation scene exceeds 128 entities"
	var entities := {}
	for entity in scene.entities:
		if not fields(entity, ["id", "kind", "position", "rotationY", "scale", "color", "parameters"]):
			return "Unsupported entity fields"
		if not identifier(entity.id) or entities.has(entity.id):
			return "Invalid or duplicate entity ID"
		entities[entity.id] = entity
		if not entity.kind in ["tree", "rock", "chest", "door", "marker"]:
			return "Unsupported entity kind"
		if not entity.position is Array or entity.position.size() != 3 or not finite(entity.position[0], -28, 28) or not finite(entity.position[1], 0, 16) or not finite(entity.position[2], -28, 28):
			return "Entity position is outside the creation bounds"
		if not finite(entity.rotationY, -180, 180) or not entity.scale is Array or entity.scale.size() != 3:
			return "Invalid entity transform"
		for value in entity.scale:
			if not finite(value, 0.25, 4):
				return "Invalid entity scale"
		var color_pattern := RegEx.new()
		color_pattern.compile("^#[a-fA-F0-9]{6}$")
		if not entity.color is String or entity.color.length() != 7 or color_pattern.search(entity.color) == null:
			return "Invalid entity color"
		var keys := []
		match entity.kind:
			"chest": keys = ["rewardId", "rewardCount"]
			"door": keys = ["initiallyOpen"]
			"marker": keys = ["label"]
		if not fields(entity.parameters, [], keys):
			return "Unsupported entity parameters"
		var p: Dictionary = entity.parameters
		if p.has("rewardId") and not identifier(p.rewardId):
			return "Invalid source-local reward ID"
		if p.has("rewardCount") and not integer(p.rewardCount, 1, 99):
			return "Invalid reward count"
		if p.has("initiallyOpen") and not p.initiallyOpen is bool:
			return "Invalid door initial state"
		if p.has("label") and (not p.label is String or p.label.length() > 80):
			return "Invalid marker label"
	var rules: Variant = scene.get("rules", [])
	if not rules is Array or rules.size() > 8:
		return "Creation scene exceeds eight rules"
	var rule_ids := {}
	for rule in rules:
		if not fields(rule, ["id", "kind", "doorId", "sequence", "script", "sha256"]):
			return "Unsupported authored rule fields"
		if not identifier(rule.id) or rule_ids.has(rule.id):
			return "Invalid or duplicate rule ID"
		rule_ids[rule.id] = true
		if rule.kind != "sequence-door" or not entities.has(rule.doorId) or entities[rule.doorId].kind != "door":
			return "Rule requires a declared door"
		if not rule.sequence is Array or rule.sequence.size() < 2 or rule.sequence.size() > 16:
			return "Rule requires 2..16 markers"
		var seen := {}
		for marker in rule.sequence:
			if not marker is String or seen.has(marker) or not entities.has(marker) or entities[marker].kind != "marker":
				return "Rule requires distinct declared markers"
			seen[marker] = true
		if rule.script != "scripts/creation/rules/" + rule.id + ".gd":
			return "Invalid rule script path"
		var hash_pattern := RegEx.new()
		hash_pattern.compile("^[a-f0-9]{64}$")
		if not rule.sha256 is String or rule.sha256.length() != 64 or hash_pattern.search(rule.sha256) == null:
			return "Invalid rule script hash"
	return ""

